-- 106: Original BrillaPrep 4MA1 beta questions, part 2.
-- Original practice content; not official Pearson questions.
PRAGMA foreign_keys = ON;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ma1_b001_021', 'topic_edx_4ma1_geo', 'subj_edexcel_igcse_math', 'edexcel_igcse', 'A right-angled triangle has shorter sides 9 cm and 12 cm. Calculate the hypotenuse.', 'multiple_choice', '["A. 15 cm","B. 13 cm","C. 18 cm","D. 21 cm"]', 'A', 'Pythagoras gives c² = 9² + 12² = 81 + 144 = 225, so c = 15 cm. Therefore the correct answer is A: 15 cm.', 'hard', 1, 1, 90, 'st_edx_4ma1_geo', 'Calculate', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ma1_b001_022', 'topic_edx_4ma1_geo', 'subj_edexcel_igcse_math', 'edexcel_igcse', 'Calculate the area of a circle of radius 6 cm in terms of π.', 'multiple_choice', '["A. 12π cm²","B. 36π cm²","C. 18π cm²","D. 72π cm²"]', 'B', 'Circle area is πr², so substituting radius 6 gives π × 6² = 36π cm². Therefore the correct answer is B: 36π cm².', 'easy', 2, 2, 90, 'st_edx_4ma1_geo', 'Calculate', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ma1_b001_023', 'topic_edx_4ma1_geo', 'subj_edexcel_igcse_math', 'edexcel_igcse', 'The exterior angle of a regular polygon is 24°. How many sides does it have?', 'multiple_choice', '["A. 12","B. 18","C. 15","D. 24"]', 'C', 'Exterior angles sum to 360°, so the number of equal angles is 360 ÷ 24 = 15. Therefore the correct answer is C: 15.', 'medium', 1, 1, 90, 'st_edx_4ma1_geo', 'Identify', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ma1_b001_024', 'topic_edx_4ma1_geo', 'subj_edexcel_igcse_math', 'edexcel_igcse', 'A prism has cross-sectional area 18 cm² and length 7 cm. Calculate its volume.', 'multiple_choice', '["A. 25 cm³","B. 72 cm³","C. 252 cm³","D. 126 cm³"]', 'D', 'Prism volume equals cross-sectional area multiplied by length: 18 × 7 = 126 cm³. Therefore the correct answer is D: 126 cm³.', 'hard', 2, 2, 90, 'st_edx_4ma1_geo', 'Calculate', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ma1_b001_025', 'topic_edx_4ma1_geo', 'subj_edexcel_igcse_math', 'edexcel_igcse', 'In a right triangle, the side opposite angle θ is 8 cm and the hypotenuse is 10 cm. Calculate sin θ.', 'multiple_choice', '["A. 0.8","B. 0.6","C. 1.25","D. 1.8"]', 'A', 'Sine equals opposite divided by hypotenuse, so sin θ = 8 ÷ 10 = 0.8. Therefore the correct answer is A: 0.8.', 'easy', 3, 3, 90, 'st_edx_4ma1_geo', 'Calculate', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ma1_b001_026', 'topic_edx_4ma1_geo', 'subj_edexcel_igcse_math', 'edexcel_igcse', 'A scale drawing uses 1:50. A wall is 8 cm on the drawing. What is its actual length?', 'multiple_choice', '["A. 0.16 m","B. 4 m","C. 40 m","D. 400 m"]', 'B', 'The actual length is 8 × 50 = 400 cm, which converts to 4 m. Therefore the correct answer is B: 4 m.', 'medium', 2, 2, 90, 'st_edx_4ma1_geo', 'Identify', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ma1_b001_027', 'topic_edx_4ma1_geo', 'subj_edexcel_igcse_math', 'edexcel_igcse', 'A cylinder has radius 2 cm and height 9 cm. Calculate its volume in terms of π.', 'multiple_choice', '["A. 18π cm³","B. 22π cm³","C. 36π cm³","D. 72π cm³"]', 'C', 'Cylinder volume is πr²h, so π × 2² × 9 = 36π cm³. Therefore the correct answer is C: 36π cm³.', 'hard', 1, 1, 90, 'st_edx_4ma1_geo', 'Calculate', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ma1_b001_028', 'topic_edx_4ma1_geo', 'subj_edexcel_igcse_math', 'edexcel_igcse', 'Two similar shapes have linear scale factor 3. What is their area scale factor?', 'multiple_choice', '["A. 3","B. 6","C. 27","D. 9"]', 'D', 'Area changes with the square of the linear scale factor, so 3² = 9. Therefore the correct answer is D: 9.', 'easy', 2, 2, 90, 'st_edx_4ma1_geo', 'Identify', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ma1_b001_029', 'topic_edx_4ma1_geo', 'subj_edexcel_igcse_math', 'edexcel_igcse', 'What single transformation maps (x, y) to (−x, y)?', 'multiple_choice', '["A. Reflection in the y-axis","B. Reflection in the x-axis","C. Rotation 90° clockwise","D. Translation left one unit"]', 'A', 'Changing only the sign of the x-coordinate mirrors every point across the y-axis. Therefore the correct answer is A: Reflection in the y-axis.', 'medium', 1, 1, 90, 'st_edx_4ma1_geo', 'Identify', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ma1_b001_030', 'topic_edx_4ma1_geo', 'subj_edexcel_igcse_math', 'edexcel_igcse', 'Vectors a = (3, −1) and b = (2, 4). Calculate a + b.', 'multiple_choice', '["A. (1, −5)","B. (5, 3)","C. (6, −4)","D. (5, −5)"]', 'B', 'Add corresponding components: 3 + 2 = 5 and −1 + 4 = 3. Therefore the correct answer is B: (5, 3).', 'hard', 3, 3, 90, 'st_edx_4ma1_geo', 'Calculate', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ma1_b001_031', 'topic_edx_4ma1_sta', 'subj_edexcel_igcse_math', 'edexcel_igcse', 'Find the mean of 6, 8, 9, 12 and 15.', 'multiple_choice', '["A. 9","B. 10.5","C. 10","D. 12"]', 'C', 'The total is 50 and there are five values, so the mean is 50 ÷ 5 = 10. Therefore the correct answer is C: 10.', 'easy', 1, 1, 90, 'st_edx_4ma1_sta', 'Identify', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ma1_b001_032', 'topic_edx_4ma1_sta', 'subj_edexcel_igcse_math', 'edexcel_igcse', 'Find the median of 3, 5, 8, 11, 14 and 19.', 'multiple_choice', '["A. 8","B. 11","C. 10","D. 9.5"]', 'D', 'With six ordered values, average the third and fourth: (8 + 11) ÷ 2 = 9.5. Therefore the correct answer is D: 9.5.', 'medium', 2, 2, 90, 'st_edx_4ma1_sta', 'Identify', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ma1_b001_033', 'topic_edx_4ma1_sta', 'subj_edexcel_igcse_math', 'edexcel_igcse', 'A fair die is rolled. What is the probability of obtaining a prime number?', 'multiple_choice', '["A. 1/2","B. 1/3","C. 2/3","D. 5/6"]', 'A', 'The prime faces are 2, 3 and 5, giving three favourable results out of six equally likely results, or 1/2. Therefore the correct answer is A: 1/2.', 'hard', 1, 1, 90, 'st_edx_4ma1_sta', 'Identify', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ma1_b001_034', 'topic_edx_4ma1_sta', 'subj_edexcel_igcse_math', 'edexcel_igcse', 'A bag has 4 red, 5 blue and 1 green counter. What is P(not blue)?', 'multiple_choice', '["A. 1/5","B. 1/2","C. 2/5","D. 3/5"]', 'B', 'Five of the ten counters are not blue, so the probability is 5/10 = 1/2. Therefore the correct answer is B: 1/2.', 'easy', 2, 2, 90, 'st_edx_4ma1_sta', 'Identify', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ma1_b001_035', 'topic_edx_4ma1_sta', 'subj_edexcel_igcse_math', 'edexcel_igcse', 'A class interval has frequency 18 and width 6. Calculate its frequency density.', 'multiple_choice', '["A. 6","B. 12","C. 3","D. 108"]', 'C', 'Frequency density is frequency divided by class width, so 18 ÷ 6 = 3. Therefore the correct answer is C: 3.', 'medium', 3, 3, 90, 'st_edx_4ma1_sta', 'Calculate', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ma1_b001_036', 'topic_edx_4ma1_sta', 'subj_edexcel_igcse_math', 'edexcel_igcse', 'The probability of rain is 0.35. What is the probability of no rain?', 'multiple_choice', '["A. 0.35","B. 0.55","C. 1.35","D. 0.65"]', 'D', 'Complementary probabilities total 1, so P(no rain) = 1 − 0.35 = 0.65. Therefore the correct answer is D: 0.65.', 'hard', 2, 2, 90, 'st_edx_4ma1_sta', 'Identify', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ma1_b001_037', 'topic_edx_4ma1_sta', 'subj_edexcel_igcse_math', 'edexcel_igcse', 'A coin is tossed twice. What is the probability of exactly one head?', 'multiple_choice', '["A. 1/2","B. 1/4","C. 3/4","D. 1"]', 'A', 'The equally likely outcomes are HH, HT, TH and TT; exactly one head occurs in two of four outcomes. Therefore the correct answer is A: 1/2.', 'easy', 1, 1, 90, 'st_edx_4ma1_sta', 'Identify', 'AO1', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ma1_b001_038', 'topic_edx_4ma1_sta', 'subj_edexcel_igcse_math', 'edexcel_igcse', 'For the values 4, 7, 7, 9, 13, what is the range?', 'multiple_choice', '["A. 6","B. 9","C. 7","D. 13"]', 'B', 'Range is maximum minus minimum, so 13 − 4 = 9. Therefore the correct answer is B: 9.', 'medium', 2, 2, 90, 'st_edx_4ma1_sta', 'Identify', 'AO2', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ma1_b001_039', 'topic_edx_4ma1_sta', 'subj_edexcel_igcse_math', 'edexcel_igcse', 'In a survey of 80 students, 28 prefer physics. Estimate the sector angle in a pie chart.', 'multiple_choice', '["A. 98°","B. 144°","C. 126°","D. 252°"]', 'C', 'The sector is 28/80 of a full turn: 28 ÷ 80 × 360° = 126°. Therefore the correct answer is C: 126°.', 'hard', 1, 1, 90, 'st_edx_4ma1_sta', 'Identify', 'AO3', 'board_edexcel');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_edx_4ma1_b001_040', 'topic_edx_4ma1_sta', 'subj_edexcel_igcse_math', 'edexcel_igcse', 'A scatter graph shows points close to a downward-sloping line. What correlation is shown?', 'multiple_choice', '["A. Strong positive correlation","B. No correlation","C. Perfect positive correlation","D. Strong negative correlation"]', 'D', 'A downward trend means one variable tends to decrease as the other increases; closeness to a line makes it strong. Therefore the correct answer is D: Strong negative correlation.', 'easy', 3, 3, 90, 'st_edx_4ma1_sta', 'Identify', 'AO1', 'board_edexcel');
